create extension if not exists pgcrypto;
create type project_visibility as enum ('PUBLIC','PRIVATE','UNLISTED');
create type project_status as enum ('DRAFT','READY','CLIENT_REVIEW','REVISION_REQUESTED','APPROVED','DELIVERED');
create table profiles (id uuid primary key references auth.users on delete cascade, role text not null default 'SUPER_ADMIN', display_name text, created_at timestamptz default now());
create table clients (id uuid primary key default gen_random_uuid(), name text not null, email text, phone text, whatsapp text, created_at timestamptz default now());
create table project_categories (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, position int default 0);
create table projects (id uuid primary key default gen_random_uuid(), client_id uuid references clients, category_id uuid references project_categories, title text not null, slug text not null unique, project_type text not null, description text, role text, location text, project_year int, cover_path text, visibility project_visibility not null default 'PRIVATE', status project_status not null default 'DRAFT', published boolean not null default false, portfolio boolean not null default false, featured boolean not null default false, selection_limit int, created_at timestamptz default now(), updated_at timestamptz default now());
create table media_assets (id uuid primary key default gen_random_uuid(), storage_bucket text not null, storage_path text not null, media_type text not null, mime_type text, width int, height int, duration numeric, poster_path text, metadata jsonb default '{}'::jsonb, created_at timestamptz default now());
create table project_media (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects on delete cascade, media_id uuid not null references media_assets on delete cascade, position int not null default 0, section text, caption text, is_downloadable boolean default false, is_featured boolean default false, is_watermarked boolean default false, visibility project_visibility default 'PRIVATE');
create table client_links (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects on delete cascade, token_hash text not null unique, expires_at timestamptz, pin_hash text, download_enabled boolean default false, selection_enabled boolean default false, comments_enabled boolean default false, approval_enabled boolean default false, active boolean default true, created_at timestamptz default now());
create table client_link_sessions (id uuid primary key default gen_random_uuid(), client_link_id uuid references client_links on delete cascade, session_hash text not null, expires_at timestamptz not null, created_at timestamptz default now());
create table client_selections (id uuid primary key default gen_random_uuid(), project_id uuid references projects on delete cascade, media_id uuid references media_assets on delete cascade, session_id uuid references client_link_sessions on delete cascade, created_at timestamptz default now(), unique(media_id,session_id));
create table client_comments (id uuid primary key default gen_random_uuid(), project_id uuid references projects on delete cascade, media_id uuid references media_assets on delete cascade, session_id uuid references client_link_sessions on delete cascade, body text not null, video_timestamp numeric, created_at timestamptz default now());
create table project_approvals (id uuid primary key default gen_random_uuid(), project_id uuid references projects on delete cascade, session_id uuid references client_link_sessions, status project_status not null, message text, created_at timestamptz default now());
create table services (id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null, description text, content jsonb default '{}'::jsonb, published boolean default false, position int default 0);
create table training_courses (id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null, content jsonb default '{}'::jsonb, published boolean default false);
create table training_sessions (id uuid primary key default gen_random_uuid(), course_id uuid references training_courses on delete cascade, starts_at timestamptz, duration text, format text, location text, price numeric, capacity int);
create table training_registrations (id uuid primary key default gen_random_uuid(), session_id uuid references training_sessions, name text not null, phone text, whatsapp text, email text not null, message text, created_at timestamptz default now());
create table inquiries (id uuid primary key default gen_random_uuid(), inquiry_type text not null, name text not null, company text, phone text, whatsapp text, email text not null, service_type text, project_date date, location text, budget text, message text not null, created_at timestamptz default now());
create table downloads (id uuid primary key default gen_random_uuid(), project_id uuid references projects, media_id uuid references media_assets, session_id uuid references client_link_sessions, kind text not null, created_at timestamptz default now());
create table site_settings (key text primary key, value jsonb not null default '{}'::jsonb, updated_at timestamptz default now());
create table social_links (id uuid primary key default gen_random_uuid(), platform text not null unique, url text not null, active boolean default true);
create table activity_logs (id uuid primary key default gen_random_uuid(), actor_id uuid, action text not null, entity_type text, entity_id uuid, metadata jsonb default '{}'::jsonb, created_at timestamptz default now());

alter table projects enable row level security; alter table project_media enable row level security; alter table media_assets enable row level security; alter table clients enable row level security; alter table client_links enable row level security; alter table client_selections enable row level security; alter table client_comments enable row level security;
create policy "published public projects" on projects for select using (published and portfolio and visibility='PUBLIC');
create policy "admins manage projects" on projects for all using (exists(select 1 from profiles where profiles.id=auth.uid() and profiles.role='SUPER_ADMIN')) with check (exists(select 1 from profiles where profiles.id=auth.uid() and profiles.role='SUPER_ADMIN'));
create policy "admins manage media" on media_assets for all using (exists(select 1 from profiles where profiles.id=auth.uid() and profiles.role='SUPER_ADMIN')) with check (exists(select 1 from profiles where profiles.id=auth.uid() and profiles.role='SUPER_ADMIN'));
create policy "admins manage clients" on clients for all using (exists(select 1 from profiles where profiles.id=auth.uid() and profiles.role='SUPER_ADMIN')) with check (exists(select 1 from profiles where profiles.id=auth.uid() and profiles.role='SUPER_ADMIN'));
